class Meeting extends DataClass implements Insertable<Meeting> {
  /// Auto-increment primary key
  final int id;

  /// UUID for future cloud sync
  final String syncId;

  /// Unix timestamp (milliseconds) of creation
  final int createdAt;

  /// Unix timestamp (milliseconds) of last update
  final int updatedAt;

  /// Soft delete flag — records are never hard-deleted
  final bool isDeleted;

  /// Creator identifier (for multi-user support in the future)
  final String? createdBy;

  /// Meeting title
  final String title;

  /// Meeting category (0=اجتماع/Meeting, 1=لقاء/Encounter)
  /// Merges the old Encounters module into this table.
  final int meetingCategory;

  /// Meeting type (general=0, administrative=1, emergency=2, etc.)
  final int meetingType;

  /// Meeting date (stored as ISO 8601 string: YYYY-MM-DD)
  final String date;

  /// Meeting time (stored as HH:mm)
  final String time;

  /// Meeting end time (stored as HH:mm, nullable)
  final String? endTime;

  /// Meeting location
  final String? location;

  /// Meeting objective / purpose
  final String? objective;

  /// Agenda items (stored as JSON array of strings)
  final String? agenda;

  /// Decisions made (stored as JSON array of strings)
  final String? decisions;

  /// Meeting outcomes / outputs (stored as JSON array of strings)
  final String? outcomes;

  /// Attendees (stored as JSON array of objects: [{name, role}])
  final String? attendees;

  /// Attachments (stored as JSON array of file paths)
  final String? attachments;

  /// Meeting status (scheduled=0, inProgress=1, completed=2, postponed=3, cancelled=4)
  final int status;

  /// Priority level (critical=0, high=1, medium=2, low=3)
  final int priority;

  /// Additional notes
  final String? notes;

  /// Minutes of meeting (محضر الاجتماع) — full text
  final String? minutes;

  /// Recurrence rule (for repeating meetings, future use)
  final String? recurrenceRule;

  /// Custom dynamic meeting type (if the user overrides the standard enum)
  final String? customMeetingType;

  /// Linked client ID (FK → clients table, nullable)
  final int? linkedClientId;

  /// Linked client name (cached label for display)
  final String? linkedClientName;

  /// Linked project ID (FK → projects table, nullable)
  final int? linkedProjectId;

  /// Linked project name (cached label for display)
  final String? linkedProjectName;

  /// Linked employee IDs (JSON array of employee IDs)
  final String? linkedEmployeeIds;

  /// Source: was this migrated from the old Encounters table?
  final bool migratedFromEncounter;
  const Meeting({
    required this.id,
    required this.syncId,
    required this.createdAt,
    required this.updatedAt,
    required this.isDeleted,
    this.createdBy,
    required this.title,
    required this.meetingCategory,
    required this.meetingType,
    required this.date,
    required this.time,
    this.endTime,
    this.location,
    this.objective,
    this.agenda,
    this.decisions,
    this.outcomes,
    this.attendees,
    this.attachments,
    required this.status,
    required this.priority,
    this.notes,
    this.minutes,
    this.recurrenceRule,
    this.customMeetingType,
    this.linkedClientId,
    this.linkedClientName,
    this.linkedProjectId,
    this.linkedProjectName,
    this.linkedEmployeeIds,
    required this.migratedFromEncounter,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['sync_id'] = Variable<String>(syncId);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    map['is_deleted'] = Variable<bool>(isDeleted);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    map['title'] = Variable<String>(title);
    map['meeting_category'] = Variable<int>(meetingCategory);
    map['meeting_type'] = Variable<int>(meetingType);
