  final String? createdBy;

  /// Full name
  final String name;

  /// Position or job title
  final String? position;

  /// Company or organization
  final String? company;

  /// Primary phone number
  final String? phoneNumber;

  /// Email address
  final String? email;

  /// Is this a VIP contact?
  final bool isVip;

  /// Notes about the contact
