class Invoice extends DataClass implements Insertable<Invoice> {
  /// Auto-increment primary key
  final int id;

  /// UUID for future cloud sync
  final String syncId;

  /// Unix timestamp (milliseconds) of creation
  final int createdAt;

  /// Unix timestamp (milliseconds) of last update
  final int updatedAt;

  /// Soft delete flag — records are never hard-deleted
  final bool isDeleted;

  /// Creator identifier (for multi-user support in the future)
  final String? createdBy;
  final String? invoiceNumber;
  final int? clientId;
  final String? clientName;
  final int? projectId;
  final String? projectName;
  final String issueDate;
  final String? dueDate;

  /// items: JSON [{description, quantity, unitPrice, discount, total}]
  final String? items;
  final double subtotal;
  final double discountAmount;
  final double discountPercent;
  final double taxAmount;
  final double taxPercent;
  final double total;
  final double paidAmount;
  final double remainingAmount;
  final String currency;

  /// status: 0=draft, 1=sent, 2=paid, 3=partial, 4=overdue, 5=cancelled
  final int status;
  final String? paymentTerms;
  final String? notes;
  final String? footer;
  final String? attachments;
  final String? pdfPath;
  const Invoice({
    required this.id,
    required this.syncId,
    required this.createdAt,
    required this.updatedAt,
    required this.isDeleted,
    this.createdBy,
    this.invoiceNumber,
    this.clientId,
    this.clientName,
    this.projectId,
    this.projectName,
    required this.issueDate,
    this.dueDate,
    this.items,
    required this.subtotal,
    required this.discountAmount,
    required this.discountPercent,
    required this.taxAmount,
    required this.taxPercent,
    required this.total,
    required this.paidAmount,
    required this.remainingAmount,
    required this.currency,
    required this.status,
    this.paymentTerms,
    this.notes,
    this.footer,
    this.attachments,
    this.pdfPath,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['sync_id'] = Variable<String>(syncId);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    map['is_deleted'] = Variable<bool>(isDeleted);
    if (!nullToAbsent || createdBy != null) {
      map['created_by'] = Variable<String>(createdBy);
    }
    if (!nullToAbsent || invoiceNumber != null) {
      map['invoice_number'] = Variable<String>(invoiceNumber);
    }
    if (!nullToAbsent || clientId != null) {
      map['client_id'] = Variable<int>(clientId);
    }
    if (!nullToAbsent || clientName != null) {
      map['client_name'] = Variable<String>(clientName);
    }
    if (!nullToAbsent || projectId != null) {
      map['project_id'] = Variable<int>(projectId);
    }
    if (!nullToAbsent || projectName != null) {
      map['project_name'] = Variable<String>(projectName);
    }
    map['issue_date'] = Variable<String>(issueDate);
    if (!nullToAbsent || dueDate != null) {
      map['due_date'] = Variable<String>(dueDate);
    }
    if (!nullToAbsent || items != null) {
      map['items'] = Variable<String>(items);
    }
    map['subtotal'] = Variable<double>(subtotal);
    map['discount_amount'] = Variable<double>(discountAmount);
    map['discount_percent'] = Variable<double>(discountPercent);
    map['tax_amount'] = Variable<double>(taxAmount);
    map['tax_percent'] = Variable<double>(taxPercent);
    map['total'] = Variable<double>(total);
    map['paid_amount'] = Variable<double>(paidAmount);
    map['remaining_amount'] = Variable<double>(remainingAmount);
    map['currency'] = Variable<String>(currency);
    map['status'] = Variable<int>(status);
    if (!nullToAbsent || paymentTerms != null) {
      map['payment_terms'] = Variable<String>(paymentTerms);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || footer != null) {
      map['footer'] = Variable<String>(footer);
    }
    if (!nullToAbsent || attachments != null) {
      map['attachments'] = Variable<String>(attachments);
    }
    if (!nullToAbsent || pdfPath != null) {
      map['pdf_path'] = Variable<String>(pdfPath);
    }
    return map;
  }

  InvoicesCompanion toCompanion(bool nullToAbsent) {
    return InvoicesCompanion(
      id: Value(id),
      syncId: Value(syncId),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      isDeleted: Value(isDeleted),
      createdBy: createdBy == null && nullToAbsent
          ? const Value.absent()
          : Value(createdBy),
      invoiceNumber: invoiceNumber == null && nullToAbsent
          ? const Value.absent()
          : Value(invoiceNumber),
      clientId: clientId == null && nullToAbsent
          ? const Value.absent()
          : Value(clientId),
      clientName: clientName == null && nullToAbsent
          ? const Value.absent()
          : Value(clientName),
      projectId: projectId == null && nullToAbsent
          ? const Value.absent()
          : Value(projectId),
