class Expense extends DataClass implements Insertable<Expense> {
  /// Auto-increment primary key
  final int id;

  /// UUID for future cloud sync
  final String syncId;

  /// Unix timestamp (milliseconds) of creation
  final int createdAt;

  /// Unix timestamp (milliseconds) of last update
  final int updatedAt;

  /// Soft delete flag — records are never hard-deleted
  final bool isDeleted;

  /// Creator identifier (for multi-user support in the future)
  final String? createdBy;
  final String title;
  final String? description;
  final double amount;
  final String currency;
  final String? category;
  final String date;
  final int? projectId;
  final String? projectName;
  final int? employeeId;
  final String? employeeName;
  final int? supplierId;
  final String? supplierName;
  final String? costCenter;

  /// paymentMethod: 0=cash, 1=bank-transfer, 2=credit-card, 3=check
  final int paymentMethod;
  final String? referenceNumber;
  final int? accountId;
  final String? attachments;

  /// status: 0=pending, 1=approved, 2=rejected, 3=paid
  final int status;
  final bool isRecurring;
  final String? recurringRule;
  final String? notes;
  const Expense({
    required this.id,
    required this.syncId,
    required this.createdAt,
    required this.updatedAt,
    required this.isDeleted,
    this.createdBy,
    required this.title,
    this.description,
    required this.amount,
    required this.currency,
    this.category,
    required this.date,
    this.projectId,
    this.projectName,
    this.employeeId,
    this.employeeName,
    this.supplierId,
    this.supplierName,
    this.costCenter,
    required this.paymentMethod,
    this.referenceNumber,
    this.accountId,
    this.attachments,
    required this.status,
    required this.isRecurring,
    this.recurringRule,
    this.notes,
  });
