class Check extends DataClass implements Insertable<Check> {
  /// Auto-increment primary key
  final int id;

  /// UUID for future cloud sync
  final String syncId;

  /// Unix timestamp (milliseconds) of creation
  final int createdAt;

  /// Unix timestamp (milliseconds) of last update
  final int updatedAt;

  /// Soft delete flag — records are never hard-deleted
  final bool isDeleted;

  /// Creator identifier (for multi-user support in the future)
  final String? createdBy;
  final String checkNumber;
  final String? bankName;
  final double amount;
  final String currency;
  final String? issueDate;
  final String dueDate;
  final String? partyName;
  final int? partyId;

  /// type: 0=incoming (مستلم), 1=outgoing (مصدر)
  final int type;

  /// status: 0=pending, 1=deposited, 2=cleared, 3=bounced, 4=cancelled
  final int status;
  final String? notes;
  final String? attachments;
  const Check({
    required this.id,
    required this.syncId,
    required this.createdAt,
    required this.updatedAt,
    required this.isDeleted,
    this.createdBy,
    required this.checkNumber,
    this.bankName,
    required this.amount,
    required this.currency,
    this.issueDate,
    required this.dueDate,
    this.partyName,
    this.partyId,
    required this.type,
    required this.status,
    this.notes,
    this.attachments,
  });
