      map['issue_date'] = Variable<String>(issueDate);
    }
    map['due_date'] = Variable<String>(dueDate);
    if (!nullToAbsent || partyName != null) {
      map['party_name'] = Variable<String>(partyName);
    }
    if (!nullToAbsent || partyId != null) {
